fn static_review(){
 fs::create_dir_all(r("static")).unwrap();let mut parents=BTreeMap::<String,BTreeMap<String,(u64,u64)>>::new();let mut helpers=vec![];
 for label in ["control","candidate"]{let receipt=read(r(format!("native/{label}/artifacts.json")));let binary=receipt["binary"].as_str().unwrap();let output=Command::new("nm").args(["-S","--defined-only",binary]).output().unwrap();assert!(output.status.success());let text=String::from_utf8(output.stdout).unwrap();let mut selected=String::new();let mut these=BTreeMap::new();
  for line in text.lines(){let f=line.split_whitespace().collect::<Vec<_>>();if f.len()!=4{continue}let symbol=f[3];if symbol.contains("g2_borrowed5apply")||symbol.contains("g2_prefix5apply"){let key=if symbol.contains("g2_borrowed"){"borrowed_true"}else if symbol.contains("Kb1_"){"owned_true"}else{"owned_false"};let start=u64::from_str_radix(f[0],16).unwrap();let size=u64::from_str_radix(f[1],16).unwrap();assert!(these.insert(key.into(),(start,size)).is_none());selected.push_str(line);selected.push('\n');let dump=Command::new("objdump").args(["-d","-C","--no-show-raw-insn"]).arg(format!("--start-address={start}")).arg(format!("--stop-address={}",start+size)).arg(binary).output().unwrap();assert!(dump.status.success());let dump=String::from_utf8(dump.stdout).unwrap();if label=="candidate"{assert!(dump.contains("g2_tail::owned")||dump.contains("g2_tail::borrowed"),"missing cold call {key}");}fs::write(r(format!("static/{label}-{key}.s")),dump).unwrap();}else if symbol.contains("g2_tail")&&(symbol.contains("5owned")||symbol.contains("8borrowed")){helpers.push(json!({"label":label,"symbol":symbol,"address":f[0],"size_hex":f[1]}));selected.push_str(line);selected.push('\n');}}
  assert_eq!(these.len(),3);parents.insert(label.into(),these);fs::write(r(format!("static/{label}-symbols.txt")),selected).unwrap();}
 assert!(helpers.len()>=2);assert!(helpers.iter().all(|h|h["label"]=="candidate"));let mut records=vec![];for(key,(address,size))in &parents["control"]{let(on_address,on_size)=parents["candidate"][key];assert!(on_size<*size,"intended extraction absent {key}");records.push(json!({"parent":key,"OFF_address":address,"OFF_bytes":size,"ON_address":on_address,"ON_bytes":on_size,"smaller_parent":true,"cold_call_in_ON":true}));}save(r("static-review.json"),&json!({"parents":records,"helpers":helpers,"source_bodies_exact":true,"static_implementation_gate":true,"combined_stack_or_RSS_saving_proven":false,"cause_of_latency_change_isolated":false}));
}
