 assert_eq!(cases.len(),22);assert_eq!(preflights.len(),9);for p in files(&r("cases")){pin(&mut pins,p);}save(r("cases.json"),&json!(cases));let base=read(format!("{Z}/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"))["environment"].clone();assert!(base.get("ZOPRO_G2_CAPTURE_DIR").is_none());for d in["stat","perf"]{fs::create_dir_all(r(d)).unwrap();}for f in["ctl","ack"]{assert!(!r(f).exists());assert!(Command::new("mkfifo").arg(r(f)).status().unwrap().success());}let(mut jobs,mut steps)=(vec![],vec![]);for c in &preflights{for v in VS{add_job(c,v,0,"preflight",&ids,&base,&mut jobs,&mut steps);}}
